import os
c = os.environ.get('REPRO_DATA_CACHE')
print('cache:', c)
if c and os.path.isdir(c):
    for root, dirs, files in os.walk(c):
        rel = os.path.relpath(root, c)
        print(rel, len(files), files[:30])
else:
    print('cache dir missing')
